class IGOWidget
{
protected:
	bool display;
public:
	virtual ~IGOWidget();
	virtual void SetDisplay(const bool d = true);
	virtual void Update(const float dt);
	virtual void Draw(void);
};

class PanelQuad
{
public:
	void SetFade(const float amt);
};

class IGOHintManager
{
public:
	enum { StandUp, ObjectApproaching };
	void SetHint(int new_hint);
};

class IGOFrontEnd
{
	char pad[0x484];
	IGOHintManager *hintManager;
public:
	IGOHintManager *GetHintManager() { return hintManager; }
};

class FrontEndManager
{
public:
	IGOFrontEnd *IGO;
};

class game
{
	char pad[0xbc];
	int active_player;
public:
	int get_active_player(void) { return active_player; }
};

class kellyslater_controller
{
	char pad[0x38];
	int super_state;
public:
	int get_super_state(void) const { return super_state; }
};

class world_dynamics_system
{
	char pad[0xf8];
	kellyslater_controller *ks_controller[2];
public:
	kellyslater_controller *get_ks_controller(int n) { return ks_controller[n]; }
};

enum { SUPER_STATE_WIPEOUT = 3 };

extern FrontEndManager frontendmanager;
extern game *g_game_ptr;
extern world_dynamics_system *g_world_ptr;

class ObjectAlertWidget : public IGOWidget
{
	static const float TIME_FADE;
	static const float TIME_ANIMATE;
	static const float SPEED_HILITE_FLASH;

	PanelQuad *objectRoot;
	float hiliteTime;
	float fade;
	int fadeDir;

	bool FindNearestObject(void);

public:
	void Update(const float dt);
};

const float ObjectAlertWidget::TIME_FADE = 0.30f;

void ObjectAlertWidget::Update(const float dt)
{
	bool	object_near = false;

	IGOWidget::Update(dt);

	fade += (dt/TIME_FADE)*float(fadeDir);
	if (fade >= 1.0f)
		fade = 1.0f;
	else if (fade <= 0.0f)
	{
		fade = 0.0f;
	}

	if ((fade <= 1.0f) && (fade >= 0.0f))
	{
		objectRoot->SetFade(fade);
	}

	if (FindNearestObject())
		object_near = true;

	if (object_near && (fade <= 1.0f))
	{
		if (fadeDir == -1 && 
			(g_world_ptr->get_ks_controller(g_game_ptr->get_active_player()))->get_super_state() != SUPER_STATE_WIPEOUT)
			frontendmanager.IGO->GetHintManager()->SetHint(IGOHintManager::ObjectApproaching);

		fadeDir = 1;
	}
	else if (!object_near)
		fadeDir = -1;
}
